import base64

b64_data = """"""

# Add missing padding
missing_padding = len(b64_data) % 4
if missing_padding:
    b64_data += '=' * (4 - missing_padding)

with open(r'c:\Users\martin\Documents\Projects\ShadowPulse_V2\logo.png', 'wb') as f:
    f.write(base64.b64decode(b64_data))
print("Decoded logo.png")
